Fixpoint ic_W (L : alayout) (i : Z) (d : nat) : list (Z * Z) :=
  match d with O => [] | Datatypes.S d' => (acache_addr L i + 4, acache_addr L i + 16) :: ic_W L (i + 1) d' end.

